}[stage] || '';

const connected = Object.entries(creds).filter(([k, v]) => v).map(([k]) => k);
console.log('[Load Credentials v5.2 HealthCoach]', {
  userId: prev.userId?.substring(0, 8) + '...',
  connected: connected.length, lang,
  hasUserKey: !!userOrKey,
  hasNutritionix: !!(creds.nutritionix_app_id && creds.nutritionix_api_key),
  hasDB: !!creds.database_url, growthStage: stage
});

return {
  json: {
    ...prev,
    credentials: creds,
    lang, i18n,
    GROWTH_GUIDANCE, stage,
    userOrKey, sysOrKey, PAID_MODEL, FREE_MODEL,
    _connected: connected,
    _persona: p
  }
};

// Build Agent Context v2 — Long-Life Memory
const payload = $input.first().json;
const persona = payload._persona || payload.persona || {};
const userId = payload.userId;

const relevantMemories    = persona.relevant_memories     || [];
const keyFacts            = persona.key_facts             || [];
const ethicalProfile      = persona.ethical_profile       || {};
const interests           = persona.interests             || [];
const preferences         = persona.preferences           || {};
const relationshipFacts   = persona.relationship_facts    || [];
const goalsAndAspirations = persona.goals_and_aspirations || [];
const physicalStats       = persona.physical_stats        || {};

function buildUserContext(p) {
  const lines = [];
  lines.push('\u{1F464} USER PROFILE');
  lines.push('Name: ' + (p.name || 'Unknown'));
  lines.push('Language: ' + (p.language_preference || 'th'));
  lines.push('Tier: ' + (p.subscriptionTier || 'FREE'));
  lines.push('Timezone: ' + (p.timezone || 'Asia/Bangkok'));

  const hasStats = Object.values(physicalStats).some(v => v != null);
  if (hasStats) {
    const s = physicalStats;
    const parts = [];
    if (s.age)       parts.push('age ' + s.age);
    if (s.gender)    parts.push(s.gender);
    if (s.weight_kg) parts.push(s.weight_kg + 'kg');
    if (s.height_cm) parts.push(s.height_cm + 'cm');
    if (parts.length) lines.push('Physical: ' + parts.join(', '));
  }

  if (p.personality_notes) lines.push('Personality: ' + p.personality_notes);

  if (keyFacts.length > 0) {
    lines.push('\n\u{1F4CC} KEY FACTS (remember these always):');
    keyFacts.slice(0, 8).forEach(f => lines.push('  \u2022 ' + f));
  }

  if (interests.length > 0) {
    lines.push('\n\u{1F4A1} INTERESTS: ' + interests.slice(0, 6).join(', '));
  }

  if (Object.keys(preferences).length > 0) {
    const prefStr = Object.entries(preferences).slice(0, 4).map(([k,v]) => k + ': ' + v).join(', ');
    lines.push('\u2699\uFE0F  PREFERENCES: ' + prefStr);
  }

  if (relationshipFacts.length > 0) {
    lines.push('\n\u2764\uFE0F  RELATIONSHIPS:');
    relationshipFacts.slice(0, 3).forEach(r => lines.push('  \u2022 ' + r));
  }

  if (goalsAndAspirations.length > 0) {
    lines.push('\n\u{1F3AF} GOALS & ASPIRATIONS:');
    goalsAndAspirations.slice(0, 4).forEach(g => lines.push('  \u2022 ' + g));
  }

  if (ethicalProfile.growth_stage) {
    lines.push('\n\u{1F331} GROWTH: Stage ' + ethicalProfile.growth_stage + '/5 (' + (ethicalProfile.growth_stage_label || '') + ')');
    if (ethicalProfile.top_strengths && ethicalProfile.top_strengths.length) {
      lines.push('   Strengths: ' + ethicalProfile.top_strengths.join(', '));
    }
  }

  if (relevantMemories.length > 0) {
    lines.push('\n\u{1F9E0} RELEVANT MEMORIES (from past conversations):');
    relevantMemories.forEach((m, i) => {
      const sim = m.similarity ? ' [' + (m.similarity*100).toFixed(0) + '% match]' : '';
      lines.push('  ' + (i+1) + '. [' + m.type + ']' + sim + ' ' + m.summary);
      if (m.insight) lines.push('     -> ' + m.insight);
    });
  }

  return lines.join('\n');
}

const userContext = buildUserContext(persona);
console.log('[BuildAgentContext] userId=' + (userId ? userId.slice(0,8) : 'unknown') + '... | facts=' + keyFacts.length + ' | memories=' + relevantMemories.length + ' | goals=' + goalsAndAspirations.length + ' | relationships=' + relationshipFacts.length);

return {
  json: {
    ...payload,
    USER_CONTEXT: userContext,
    _context_built: true,
    _facts_count: keyFacts.length,
    _memories_count: relevantMemories.length
  }
};

const input    = JSON.parse($input.first().json.query || '{}');
const query    = input.query || input.q || '';
const limit    = input.limit || 3;
const ctx      = $('Load Credentials').first().json;
const creds    = ctx.credentials || {};
const i18n     = ctx.i18n || {};
const userId   = ctx.userId;
const dbUrl    = creds.database_url || process.env.DATABASE_URL || '';
const persona  = ctx._persona || ctx.persona || {};
const tokens   = persona.tokens || {};
const embedKey = tokens.openrouter_access_token || process.env.OPENROUTER_API_KEY || '';

if (!dbUrl)                     return { json: { error: `Database ${i18n.not_connected||'not connected'}`, memories: [] } };
if (!query || query.length < 3) return { json: { error: 'Query too short (min 3 chars)', memories: [] } };
if (!embedKey)                  return { json: { error: 'OpenRouter key not configured', memories: [] } };

try {
  const embedRes = await fetch('https://openrouter.ai/api/v1/embeddings', {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${embedKey}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: 'openai/text-embedding-3-small', input: query })
  });
  if (!embedRes.ok) {
    const err = await embedRes.text();
    return { json: { error: `Embed failed: ${embedRes.status} ${err}`, memories: [] } };
  }
  const embedData = await embedRes.json();
  const embedding = embedData.data?.[0]?.embedding;
  if (!embedding || !Array.isArray(embedding))
    return { json: { error: 'No embedding returned', memories: [] } };

  const { Pool } = require('pg');
  const pool = new Pool({ connectionString: dbUrl });
  const vectorStr = `[${embedding.join(',')}]`;
  const result = await pool.query(
    `SELECT content, metadata, created_at,
            1 - (embedding <=> $1::vector) AS similarity
     FROM user_data_schema.memory_embeddings
     WHERE user_id = $2 AND embedding IS NOT NULL
       AND 1 - (embedding <=> $1::vector) > 0.6
     ORDER BY embedding <=> $1::vector LIMIT $3`,
    [vectorStr, userId, limit]
  );
  await pool.end();
  const memories = result.rows.map(r => ({
    content:    r.content,
    similarity: parseFloat(r.similarity.toFixed(3)),
    metadata:   r.metadata || {},
    date:       new Date(r.created_at).toLocaleDateString('th-TH')
  }));
  if (memories.length === 0)
    return { json: { message: 'No relevant memories found', memories: [], query } };
  return { json: { memories, count: memories.length, query } };
} catch(err) {
  return { json: { error: `${i18n.error||'Error'}: ${err.message}`, memories: [] } };
}

const input      = JSON.parse($input.first().json.query || '{}');
const ctx        = $('Load Credentials').first().json;
const creds      = ctx.credentials || {};
const i18n       = ctx.i18n || {};
const lookupType = (input.lookup_type || 'food_search').toLowerCase();
const nxAppId    = creds.nutritionix_app_id || '';
const nxKey      = creds.nutritionix_api_key || '';

if (!nxAppId || !nxKey)
  return { json: { error: `Nutritionix ${i18n.not_connected||'not connected'}`, help: i18n.configure } };

const headers = { 'x-app-id': nxAppId, 'x-app-key': nxKey, 'Content-Type': 'application/json' };

try {
  if (lookupType === 'food_search') {
    if (!input.query)
      return { json: { error: i18n.query_required || 'query required (e.g. fried rice 1 plate)' } };
    const res = await fetch('https://trackapi.nutritionix.com/v2/natural/nutrients', {
      method: 'POST', headers,
      body: JSON.stringify({ query: input.query, timezone: 'Asia/Bangkok' })
    });
    if (!res.ok) {
      const errText = await res.text();
      return { json: { error: `Nutritionix HTTP ${res.status}: ${errText.slice(0, 200)}` } };
    }
    const data  = await res.json();
    const foods = (data.foods || []).map(f => ({
      name:      f.food_name,
      serving:   `${f.serving_qty} ${f.serving_unit} (${f.serving_weight_grams}g)`,
      calories:  Math.round(f.nf_calories),
      protein_g: Math.round((f.nf_protein || 0) * 10) / 10,
      carbs_g:   Math.round((f.nf_total_carbohydrate || 0) * 10) / 10,
      fat_g:     Math.round((f.nf_total_fat || 0) * 10) / 10,
      fiber_g:   Math.round((f.nf_dietary_fiber || 0) * 10) / 10,
      sodium_mg: Math.round(f.nf_sodium || 0)
    }));
    return { json: { foods, total_calories: foods.reduce((s, f) => s + f.calories, 0), count: foods.length } };
  }
  if (lookupType === 'exercise_calories') {
    if (!input.exercise)
      return { json: { error: 'exercise name required (e.g. running, swimming, cycling)' } };
    const persona = ctx._persona || ctx.persona || {};
    const weight  = parseFloat(input.weight_kg || persona.physical_stats?.weight_kg || 70);
    const query   = input.duration_min
      ? `${input.exercise} for ${input.duration_min} minutes`
      : input.exercise;
    const res = await fetch('https://trackapi.nutritionix.com/v2/natural/exercise', {
      method: 'POST', headers,
      body: JSON.stringify({ query, weight_kg: weight })
    });
    if (!res.ok) {
      const errText = await res.text();
      return { json: { error: `Nutritionix HTTP ${res.status}: ${errText.slice(0, 200)}` } };
    }
    const data      = await res.json();
    const exercises = (data.exercises || []).map(e => ({
      name:            e.name,
      duration_min:    e.duration_min,
      calories_burned: Math.round(e.nf_calories)
    }));
    return { json: { exercises, total_calories_burned: exercises.reduce((s, e) => s + e.calories_burned, 0), weight_used_kg: weight } };
  }
  return { json: { error: `Unknown lookup_type: ${lookupType}. Use: food_search | exercise_calories` } };
} catch(e) {
  return { json: { error: `${i18n.error||'Error'}: ${e.message}` } };
}

const input      = JSON.parse($input.first().json.query || '{}');
const ctx        = $('Load Credentials').first().json;
const i18n       = ctx.i18n || {};
const lookupType = (input.lookup_type || 'search_exercise').toLowerCase();

try {
  if (lookupType === 'search_exercise') {
    if (!input.query)
      return { json: { error: i18n.query_required || 'query required (e.g. bench press, squat, deadlift)' } };
    const url = `https://wger.de/api/v2/exercise/search/?term=${encodeURIComponent(input.query)}&language=english&format=json`;
    const res = await fetch(url);
    if (!res.ok) throw new Error(`Wger HTTP ${res.status}`);
    const data    = await res.json();
    const results = (data.suggestions || []).slice(0, 8).map(s => ({
      id:       s.data?.id,
      name:     s.value,
      category: s.data?.category?.name
    }));
    return { json: { results, count: results.length, tip: 'Use exercise_detail with id for full instructions and muscle groups' } };
  }
  if (lookupType === 'exercise_detail') {
    if (!input.exercise_id)
      return { json: { error: 'exercise_id required (get from search_exercise results)' } };
    const res = await fetch(`https://wger.de/api/v2/exerciseinfo/${input.exercise_id}/?format=json`);
    if (!res.ok) return { json: { error: `Exercise ID ${input.exercise_id} not found` } };
    const d       = await res.json();
    const engInfo = d.translations?.find(t => t.language === 2) || d.translations?.[0] || {};
    return { json: {
      id:                d.id,
      name:              engInfo.name || d.name || 'Unknown',
      category:          d.category?.name,
      muscles_primary:   (d.muscles || []).map(m => m.name_en),
      muscles_secondary: (d.muscles_secondary || []).map(m => m.name_en),
      equipment:         (d.equipment || []).map(e => e.name),
      description:       (engInfo.description || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 600) || 'No description available'
    }};
  }
  return { json: { error: `Unknown lookup_type: ${lookupType}. Use: search_exercise | exercise_detail` } };
} catch(e) {
  return { json: { error: `${i18n.error||'Error'}: ${e.message}` } };
}

const input  = JSON.parse($input.first().json.query || '{}');
const ctx    = $('Load Credentials').first().json;
const creds  = ctx.credentials || {};
const i18n   = ctx.i18n || {};
const action = (input.action || 'view_history').toLowerCase();
const userId = ctx.userId;
const dbUrl  = creds.database_url || process.env.DATABASE_URL || '';

if (!dbUrl)
  return { json: { error: `Database ${i18n.not_connected||'not connected'}`, help: i18n.configure } };

const { Pool } = require('pg');
const pool = new Pool({ connectionString: dbUrl });

try {
  if (action === 'log_health') {
    if (!input.metric_type || input.value === undefined)
      return { json: { error: i18n.metric_required || 'metric_type and value required' } };
    const metric = input.metric_type.toLowerCase();
    const value  = parseFloat(input.value);
    const notes  = input.notes || '';
    if (isNaN(value)) return { json: { error: 'value must be a number' } };
    await pool.query(
      `INSERT INTO user_data_schema.health_log (user_id, metric_type, value, notes, logged_at) VALUES ($1, $2, $3, $4, NOW())`,
      [userId, metric, value, notes]
    );
    await pool.end();
    return { json: { success: true, message: i18n.success || 'Logged', metric, value, notes } };
  }
  if (action === 'view_history') {
    if (!input.metric_type)
      return { json: { error: i18n.metric_required || 'metric_type required' } };
    const days   = parseInt(input.days || 7);
    const metric = input.metric_type.toLowerCase();
    const result = await pool.query(
      `SELECT value, notes, logged_at FROM user_data_schema.health_log WHERE user_id = $1 AND metric_type = $2 AND logged_at >= NOW() - INTERVAL '${days} days' ORDER BY logged_at ASC`,
      [userId, metric]
    );
    await pool.end();
    const rows   = result.rows;
    const values = rows.map(r => parseFloat(r.value));
    const avg    = values.length ? Math.round(values.reduce((a, b) => a + b, 0) / values.length * 10) / 10 : null;
    return { json: { metric, days, records: rows, count: rows.length, avg, min: values.length ? Math.min(...values) : null, max: values.length ? Math.max(...values) : null } };
  }
  await pool.end();
  return { json: { error: `Unknown action: ${action}. Use: log_health | view_history` } };
} catch(err) {
  try { await pool.end(); } catch(e) {}
  return { json: { error: `${i18n.error||'Error'}: ${err.message}` } };
}

const input   = JSON.parse($input.first().json.query || '{}');
const ctx     = $('Load Credentials').first().json;
const i18n    = ctx.i18n || {};
const lang    = ctx.lang || 'th';
const type    = (input.type || 'bmi').toLowerCase();
const persona = ctx._persona || ctx.persona || {};
const stats   = persona.physical_stats || {};
const localLang = ['th','en','ja','zh'].includes(lang) ? lang : 'en';

const bmiCategories = {
  underweight: { th:'น้ำหนักน้อย (Underweight)', en:'Underweight',    ja:'低体重',     zh:'体重过轻'     },
  normal:      { th:'ปกติ (Normal)',              en:'Normal (Asian)', ja:'標準',       zh:'正常'         },
  overweight:  { th:'เริ่มอ้วน (Overweight)',     en:'Overweight',     ja:'過体重',     zh:'超重'         },
  obese1:      { th:'อ้วน (Obese class 1)',        en:'Obese class 1',  ja:'肥満1度',    zh:'肥胖一级'     },
  obese2:      { th:'อ้วนมาก (Obese class 2+)',    en:'Obese class 2+', ja:'肥満2度以上', zh:'肥胖二级以上' }
};
const getBmiCat = (bmi) => {
  const key = bmi < 18.5 ? 'underweight' : bmi < 23 ? 'normal' : bmi < 25 ? 'overweight' : bmi < 30 ? 'obese1' : 'obese2';
  return bmiCategories[key][localLang] || bmiCategories[key]['en'];
};

try {
  if (type === 'bmi') {
    const weight = parseFloat(input.weight_kg || input.weight || stats.weight_kg || 0);
    const height = parseFloat(input.height_cm || input.height || stats.height_cm || 0);
    if (!weight || !height) return { json: { error: i18n.weight_height_required || 'weight_kg and height_cm required' } };
    const bmi = weight / Math.pow(height / 100, 2);
    return { json: { bmi: parseFloat(bmi.toFixed(2)), category: getBmiCat(bmi), weight_kg: weight, height_cm: height, message: `BMI: ${bmi.toFixed(1)} — ${getBmiCat(bmi)}` } };
  }
  if (type === 'tdee') {
    const weight   = parseFloat(input.weight_kg || input.weight || stats.weight_kg || 0);
    const height   = parseFloat(input.height_cm || input.height || stats.height_cm || 0);
    const age      = parseInt(input.age || stats.age || 0);
    const gender   = (input.gender || stats.gender || 'male').toLowerCase();
    const activity = (input.activity_level || input.activity || 'moderate').toLowerCase();
    if (!weight || !height || !age) return { json: { error: 'weight_kg, height_cm and age required' } };
    const bmr = gender === 'female' ? (10 * weight) + (6.25 * height) - (5 * age) - 161 : (10 * weight) + (6.25 * height) - (5 * age) + 5;
    const factors = { sedentary:1.2, light:1.375, moderate:1.55, active:1.725, very_active:1.9 };
    const tdee    = Math.round(bmr * (factors[activity] || 1.55));
    return { json: { bmr: Math.round(bmr), tdee, activity_level: activity, weight_loss_cal: tdee - 500, weight_gain_cal: tdee + 300, message: `BMR: ${Math.round(bmr)} | TDEE: ${tdee} kcal/day | ลด: ${tdee-500} | เพิ่ม: ${tdee+300}` } };
  }
  if (type === 'ideal_weight') {
    const height = parseFloat(input.height_cm || input.height || stats.height_cm || 0);
    const gender = (input.gender || stats.gender || 'male').toLowerCase();
    if (!height) return { json: { error: 'height_cm required' } };
    const ideal = gender === 'female' ? 45.5 + 0.9 * (height - 152.4) : 50.0 + 0.9 * (height - 152.4);
    return { json: { height_cm: height, gender, ideal_weight: parseFloat(ideal.toFixed(1)), healthy_range: `${(ideal - 5).toFixed(1)}–${(ideal + 5).toFixed(1)} kg`, message: `Ideal weight for ${height}cm ${gender}: ${ideal.toFixed(1)} kg` } };
  }
  return { json: { error: `Unknown type: ${type}. Use: bmi | tdee | ideal_weight` } };
} catch(err) {
  return { json: { error: `${i18n.error||'Error'}: ${err.message}` } };
}

const input    = JSON.parse($input.first().json.query || '{}');
const goal     = input.goal  || 'general_fitness';
