const persona  = ctx._persona || ctx.persona || {};
const tokens   = persona.tokens || {};
const orKey    = tokens.openrouter_access_token || ctx.sysOrKey || process.env.OPENROUTER_API_KEY || '';
const langName = { th:'Thai', en:'English', ja:'Japanese', zh:'Chinese' }[lang] || 'English';
const stats    = persona.physical_stats || {};

if (!orKey) return { json: { error: 'OpenRouter API key not configured' } };

try {
  const statsStr = Object.keys(stats).length ? `User stats: ${Object.entries(stats).map(([k,v]) => `${k}=${v}`).join(', ')}.` : '';
  const prompt = `Create a ${days}-day/week workout plan for a ${level} with goal: ${goal.replace(/_/g,' ')}${focus ? ', focus: ' + focus : ''}.\n${statsStr}\nProvide: exercise names, sets, reps, rest time. Keep it practical and safe. Include a safety disclaimer.\nRespond in ${langName}. Format clearly with days and exercises.`;
  const res = await fetch('https://openrouter.ai/api/v1/chat/completions', {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${orKey}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: 'meta-llama/llama-3.3-70b-instruct:free', max_tokens: 1500, messages: [{ role: 'system', content: `You are a certified personal trainer. Respond in ${langName}. Provide safe, evidence-based advice.` }, { role: 'user', content: prompt }] })
  });
  if (!res.ok) throw new Error(`OpenRouter HTTP ${res.status}`);
  const data = await res.json();
  const plan = data.choices?.[0]?.message?.content;
  if (!plan) throw new Error('Empty response from LLM');
  return { json: { goal, level, days_per_week: days, focus, plan, message: plan } };
} catch(err) {
  return { json: { error: `${i18n.error||'Error'}: ${err.message}` } };
}

