try {
  const q = encodeURIComponent(drug);
  let result;
  const res1 = await fetch(`https://api.fda.gov/drug/label.json?search=openfda.brand_name:"${q}"&limit=1`);
  if (res1.ok) { const d1 = await res1.json(); result = d1.results?.[0]; }
